export const analyticalMechanicsKinds=['polar-generalized-velocity-force-metric','double-pendulum-generalized-mass-metric','free-particle-action-boundary-gauge','harmonic-action-stationary-saddle','polar-lagrange-newton-equivalence','double-pendulum-lagrange-dynamics','polar-hamiltonian-legendre-map','time-gauge-hamiltonian-energy','poisson-observable-canonical-flow','angular-momentum-poisson-algebra','four-dimensional-symplectic-maps','lagrangian-momentum-graphs','noether-point-symmetry-defects','noether-boost-time-boundaries','routh-cyclic-momentum-reduction','circle-dirac-constraint-geometry','uniform-force-hamilton-jacobi-family','oscillator-hamilton-jacobi-caustic-atlas','quartic-discrete-action-splitting','circle-rattle-projection-phase']as const;
export type AnalyticalMechanicsKind=typeof analyticalMechanicsKinds[number];
export const isAnalyticalMechanicsKind=(id:string):id is AnalyticalMechanicsKind=>(analyticalMechanicsKinds as readonly string[]).includes(id);
